diff --git a/packages/svelte/src/internal/client/dom/elements/attributes.js b/packages/svelte/src/internal/client/dom/elements/attributes.js
index 5db685c..bbdc674 100644
--- a/packages/svelte/src/internal/client/dom/elements/attributes.js
+++ b/packages/svelte/src/internal/client/dom/elements/attributes.js
@@ -516,7 +516,12 @@ export function attribute_effect(
 		var select = /** @type {HTMLSelectElement} */ (element);

 		effect(() => {
-			select_option(select, /** @type {Record<string | symbol, any>} */ (prev).value);
+			var current = /** @type {Record<string | symbol, any>} */ (prev);
+
+			if (current && 'value' in current) {
+				select_option(select, current.value);
+			}
+
 			init_select(select);
 		});
 	}
